//! Anchor's framework errors.

use crate::app::errors::{Known, coded};

/// Anchor's own error enum, regenerated by `scripts/anchor_errors.py`.
const TSV: &str = include_str!("errors.tsv");

/// Anchor reserves codes below this for the framework; at and above it are the
/// program's own `#[error_code]` variants.
pub const USER_OFFSET: u32 = 6000;

/// Parsed rows of [`TSV`]. Public so tests can assert the file is whole.
pub fn rows() -> impl Iterator<Item = (u32, Known)> {
    coded(TSV)
}

pub fn lookup(code: u32) -> Option<Known> {
    rows().find(|(row, _)| *row == code).map(|(_, known)| known)
}
